    }
    return sequence(planned);
}

export function atSequence(source: RankSequence, index: bigint): RankValue {
    if (index < 0n) throw new MissingValueError('sequence index out of bounds');
    if (source.plan.size.kind === 'exact' && index >= source.plan.size.value) {
        throw new MissingValueError(`sequence index out of bounds: ${index}`);
    }

    const planned = source.plan.at?.(index);
    if (planned !== undefined) return planned;

    let current = 0n;
    for (const value of source.plan.iterate()) {
        checkpoint('reading sequence');
        if (current === index) return value;
        current += 1n;
    }
    throw new MissingValueError(`sequence index out of bounds: ${index}`);
}

/** Positional prefixes and tails; array views and sequence plans stay lazy. */
export function takeDropValue(source: RankValue, count: RankValue, drop = false): RankValue {
    const name = drop ? 'drop' : 'take';
    if (typeof count !== 'bigint' || count < 0n) {
        throw new RankError(`${name} expects a nonnegative integer count`);
    }
    const access = sliceSource(source);
    if (!access) throw new RankError(`${name} expects text, an array or a sequence`);
    return access.slice(count, drop);
}

export function mapSequence(
    source: RankSequence,
    name: string,
    operation: (value: RankValue) => RankValue,
    pure = false,
    captures?: readonly ReadonlyMap<string, RankValue>[],
): RankSequence {
    const sourcePlan = source.plan;
    return sequence({
        name: `${sourcePlan.name} ${name}`,
        replay: sourcePlan.replay && pure ? 'pure' : undefined,
        singlePass: sourcePlan.singlePass,
        captures: [...sourcePlan.captures ?? [], ...captures ?? []],
        size: sourcePlan.size,
        *iterate() {
            for (const value of sourcePlan.iterate()) yield operation(value);
        },
    });
}

export function scanSequence(
    source: RankSequence,
    name: string,
    seed: RankValue | undefined,
    operation: (left: RankValue, right: RankValue) => RankValue,
    pure = false,
    captures?: readonly ReadonlyMap<string, RankValue>[],
): RankSequence {
    const sourcePlan = source.plan;
    return sequence({
        name: `${sourcePlan.name} scan ${name}`,
        replay: sourcePlan.replay && pure && typeof seed !== 'object' ? 'pure' : undefined,
        singlePass: sourcePlan.singlePass,
        size: scanSize(sourcePlan.size, seed !== undefined),
        captures: [...sourcePlan.captures ?? [], ...captures ?? []],
        *iterate() {
            let accumulated = seed;
            if (accumulated !== undefined) yield accumulated;
            for (const value of sourcePlan.iterate()) {
                accumulated = accumulated === undefined
                    ? value
                    : operation(accumulated, value);
                yield accumulated;
            }
        },
    });
}

export function firstWhereValue(
    source: RankValue,
    mask: RankValue,
    returnIndex = false,
): RankValue {
    validateAlignedSizes(source, mask, 'first where');
    if (isRankSequence(source) && isRankSequenceMask(mask) && mask.source === source) {
        let index = 0n;
        for (const value of source.plan.iterate()) {
            if (mask.predicate.test(value)) return returnIndex ? index : value;
            index += 1n;
        }
        throw new MissingValueError(`first${returnIndex ? ' index' : ''} where found no matching value`);
    }
    const values = rankOneValues(source, 'first where');
    const selected = maskValues(source, mask, 'first where');
    let index = 0n;
    while (true) {
        const value = values.next();
        const choice = selected.next();
        if (value.done || choice.done) {
            if (value.done !== choice.done) throw new RankError('first where source and mask have different lengths');
            break;
        }
        if (choice.value) return returnIndex ? index : value.value;
        index += 1n;
    }
    throw new MissingValueError(`first${returnIndex ? ' index' : ''} where found no matching value`);
}

/** Boolean sequences that select by position, made by combining masks of different values. */
const positionalMasks = new WeakSet<RankSequence>();

export function positionalMask(plan: SequencePlan): RankSequence {
    const result = sequence(plan);
    positionalMasks.add(result);
    return result;
}

export function isPositionalMask(value: RankValue): value is RankSequence {
    return isRankSequence(value) && positionalMasks.has(value);
}

/** Preserve internal mask identity when an execution owner replaces a plan. */
export function withSequencePlan(source: RankSequence, plan: SequencePlan): RankSequence {
    const result = { ...source, plan };
    if (positionalMasks.has(source)) positionalMasks.add(result);
    return result;
}

/**
 * A mask is positional: its first flag selects the first item, whatever value
 * it was made from. It may be shorter than the source, which ends the
 * selection; a source that ends first leaves flags with nothing to select.
 */
export function positionalSelection(source: RankValue, mask: RankValue): RankSequence {
    const plan = isRankSequence(source) ? source.plan : undefined;
    return sequence({
        name: `${plan?.name ?? 'values'} selected`,
        singlePass: plan?.singlePass ?? false,
        size: { kind: 'unknown' },
        captures: plan?.captures,
        *iterate() {
            const values = rankOneValues(source, 'selection');
            const flags = rankOneValues(mask, 'selection');
            while (true) {
                const flag = flags.next();
                if (flag.done) return;
                const value = values.next();
                if (value.done) throw new RankError('mask is longer than the values it selects from');
                if (typeof flag.value !== 'boolean') throw new RankError('selection expects a boolean mask');
                checkpoint('reading sequence');
                if (flag.value) yield value.value;
                else passOver();
            }
        },
    });
}

/** Where a bound clause looks: a test of each item, or a mask read beside it. */
export type BoundCondition =
    | { readonly test: (item: RankValue) => boolean }
    | { readonly mask: RankValue };

/**
 * `till` keeps the leading items before the first that meets the condition;
 * `from` keeps the rest, starting with that item. A mask shorter than the
 * source ends the search where it ends: it says nothing about later items.
 */
export function boundValue(source: RankValue, condition: BoundCondition, mode: 'till' | 'from'): RankValue {
    const operation = mode;
    const tests = (): (() => IteratorResult<boolean> | undefined) => {
        if ('test' in condition) return () => undefined;
        const mask = condition.mask;
        if (isRankSequenceMask(mask) && mask.source !== source) {
            throw new RankError(`${operation} mask belongs to a different sequence`);
        }
        const flags = maskValues(source, mask, operation);
        return () => flags.next();
    };
    const test = 'test' in condition ? condition.test : undefined;
    function* bounded(values: Iterator<RankValue>): Generator<RankValue> {
        const flag = tests();
        let started = false;
        while (true) {
            const value = values.next();
            if (value.done) return;
            checkpoint('reading sequence');
            if (started) { yield value.value; continue; }
            let hit: boolean;
            if (test) hit = test(value.value);
            else {
                const next = flag()!;
                if (next.done) return;
                hit = next.value;
            }
            if (mode === 'till') {
                if (hit) return;
                yield value.value;
            } else if (hit) {
                started = true;
                yield value.value;
            } else passOver();
        }
    }
    if (isRankSequence(source)) {
        const sourcePlan = source.plan;
        return sequence({
            name: `${sourcePlan.name} ${mode}`,
            singlePass: sourcePlan.singlePass,
            size: mode === 'till' || sourcePlan.size.kind !== 'infinite' ? { kind: 'unknown' } : sourcePlan.size,
            captures: sourcePlan.captures,
            *iterate() { yield* bounded(sourcePlan.iterate()); },
        });
    }
    const result = [...bounded(rankOneValues(source, operation))];
    if (typeof source === 'string') return result.join('');
    return ownedArray(result);
}

function* rankOneValues(value: RankValue, operation: string): IterableIterator<RankValue> {
    if (isRankArray(value)) {
        if (value.shape.length !== 1) throw new RankError(`${operation} expects a rank-1 source`);
        for (let index = 0; index < value.shape[0]; index += 1) {
            yield readArrayItem(value, index);
        }
        return;
    }
    if (isRankQueue(value)) { yield* value.items; return; }
    if (typeof value === 'string') { yield* value; return; }
    if (isRankSequence(value)) { yield* value.plan.iterate(); return; }
    throw new RankError(`${operation} expects a rank-1 source`);
}

function* maskValues(
    source: RankValue,
    mask: RankValue,
    operation: string,
): IterableIterator<boolean> {
    if (isRankSequence(source) && isRankSequenceMask(mask) && mask.source === source) {
        for (const value of source.plan.iterate()) yield mask.predicate.test(value);
        return;
    }
    for (const value of rankOneValues(mask, operation)) {
        if (typeof value !== 'boolean') throw new RankError(`${operation} expects a boolean mask`);
        yield value;
    }
}

function validateAlignedSizes(source: RankValue, mask: RankValue, operation: string): void {
    const sourceSize = rankOneSize(source, operation);
    const maskSize = rankOneSize(mask, operation);
    if (sourceSize !== undefined && maskSize !== undefined && sourceSize !== maskSize) {
        throw new RankError(`${operation} mask length ${maskSize} does not match source length ${sourceSize}`);
    }
}

function rankOneSize(value: RankValue, operation: string): bigint | undefined {
    if (isRankArray(value)) {
        if (value.shape.length !== 1) throw new RankError(`${operation} expects a rank-1 source`);
        return BigInt(value.shape[0]);
    }
    if (isRankQueue(value)) return BigInt(value.items.length);
    if (typeof value === 'string') return BigInt([...value].length);
    if (isRankSequence(value)) {
        return value.plan.size.kind === 'exact' ? value.plan.size.value : undefined;
    }
    throw new RankError(`${operation} expects a rank-1 source`);
}

function scanSize(size: SequenceSize, seeded: boolean): SequenceSize {
    if (size.kind !== 'exact') return size;
    return { kind: 'exact', value: size.value + (seeded ? 1n : 0n) };
}

export function zipSequences(
    left: RankSequence,
    right: RankSequence,
    name: string,
    operation: (left: RankValue, right: RankValue) => RankValue,
    pure = false,
): RankSequence {
    return sequence({
        name: `${left.plan.name} ${name} ${right.plan.name}`,
        replay: left.plan.replay && right.plan.replay && pure ? 'pure' : undefined,
        singlePass: left.plan.singlePass || right.plan.singlePass,
        size: zippedSize(left.plan.size, right.plan.size),
        *iterate() {
            const a = left.plan.iterate();
            const b = right.plan.iterate();
            while (true) {
                const nextA = a.next();
                const nextB = b.next();
                if (nextA.done || nextB.done) return;
                yield operation(nextA.value, nextB.value);
            }
        },
    });
}

/** Reject known sequence masks before an endless source is traversed.
 * Other inputs validate their cells at numeric demand, without an extra scan. */
export function numericSource(value: RankValue, operation?: string): RankValue {
    if ((isRankSequenceMask(value) || isPositionalMask(value)) && value.plan.size.kind === 'infinite') {
        const hint = operation && booleanReductionHint(operation);
        if (hint) throw new RankError(hint, 'TypeError');
    }
    return value;
}

export function sequenceValues(value: RankValue, operation: string): Iterable<RankValue> {
    if (!isRankSequence(value)) return [value];
    if (value.plan.size.kind === 'infinite') {
        throw new RankError(`${operation} requires a bounded sequence`);
    }
    return { [Symbol.iterator]: () => interruptibleValues(value.plan.iterate(), operation)[Symbol.iterator]() };
}

/** Mixed collection arithmetic uses the shape of the sequence's stacked cells.
 * Keep scalar mapping and two-stream zipping on their existing lazy paths. */
export function arraySequenceOperands(left: RankValue, right: RankValue): [RankValue, RankValue] {
    if (isRankSequence(left) && (isRankArray(right) || isRankQueue(right))) {
        left = materializeSequence(left);
    } else if (isRankSequence(right) && (isRankArray(left) || isRankQueue(left))) {
        right = materializeSequence(right);
    }
    return [left, right];
}

/** A tensor operand with the axes of copy. Proven scalar, addressable,
 * replayable sources need no eager traversal; other sources stack once. */
export function sequenceArrayOperand(value: RankValue): RankValue {
    if (!isRankSequence(value)) return value;
    const plan = value.plan;
    if (plan.size.kind !== 'exact' || !plan.scalarItems || !plan.at
        || !plan.replay || plan.singlePass) return materializeSequence(value);
    const size = safeDimension(plan.size.value, 'sequence operand size');
    return derivedArray([size], [value], index => atSequence(value, BigInt(index)), isKnownFileFree(value));
}

export function materializeSequence(source: RankSequence): RankArray {
    const selected = materializeMaskSelection(source);
    if (selected) return selected;
    if (source.plan.size.kind === 'infinite') {
        throw new RankError('cannot materialize an infinite sequence');
    }
    const range = arithmeticRange(source.plan);
    if (range && range.count <= MAX_HELD_CELLS) {
        // A range is computed rather than iterated, straight into packed cells.
        const size = Number(range.count);
        const last = range.start + (range.count - 1n) * range.step;
        if (size >= 64 && range.start >= -2147483648n && range.start <= 2147483647n
            && last >= -2147483648n && last <= 2147483647n) {
            const cells = new Int32Array(size), first = Number(range.start), step = Number(range.step);
            for (let start = 0; start < size; start += 4096) {
                const end = Math.min(size, start + 4096);
                checkpoint('materializing sequence', end - start);
                let value = first + start * step;
                for (let i = start; i < end; i++, value += step) cells[i] = value;
            }
            return registerArrayRange(typedArray(cells), range);
        }
        const cells = new IntegerCells(size);
        for (let start = 0; start < size; start += 4096) {
            const end = Math.min(size, start + 4096);
            checkpoint('materializing sequence', end - start);
            let value = range.start + BigInt(start) * range.step;
            for (let i = start; i < end; i++, value += range.step) cells.set(i, value);
        }
        return registerArrayRange(cells.array([size]), range);
    }
    return completeNativeSequence(source.plan)
        ?? stackItems(interruptibleValues(source.plan.iterate(), 'materializing sequence'), undefined, 'sequence');
}

/**
 * Dense array of the items along the frame axes. Array items with one shape
 * are stacked, their axes following the frame; scalar or record items fill the
 * frame directly. The frame defaults to one axis holding every item.
 */
export function stackItems(
    values: Iterable<RankValue>,
    frame: readonly number[] | undefined,
    source: 'sequence' | 'array' | 'collection',
): RankArray {
    const mismatch = () => new RankError(`materialized ${source} items must have the same shape`, 'DimensionMismatch');
    const items: RankValue[] = [];
    let cellShape: readonly number[] | undefined;
    let arrays: boolean | undefined;
    let count = 0;
    for (const value of values) {
        checkpoint(`materializing ${source}`);
        const array = isRankArray(value);
        arrays ??= array;
        if (arrays !== array) throw mismatch();
        if (array) {
            cellShape ??= value.shape;
            if (cellShape.length !== value.shape.length
                || cellShape.some((size, axis) => size !== value.shape[axis])) {
                throw mismatch();
            }
            const size = value.shape.reduce((product, dimension) => product * dimension, 1);
            for (let index = 0; index < size; index += 1) {
                checkpoint(`materializing ${source}`);
                items.push(readArrayItem(value, index));
            }
        } else {
            items.push(value);
        }
        count += 1;
    }
    return ownedArray(items, [...(frame ?? [count]), ...(cellShape ?? [])]);
}

export function reduceSequence(value: RankSequence, operation: string): RankValue | undefined {
    const planned = value.plan.reduce?.(operation);
    if (planned !== undefined) return planned;
    // Counting true mask items is counting the source items selected by the
    // same predicate. Preserve native reductions such as tree distance bounds.
    if (operation === 'count' && isRankSequenceMask(value)) {
        return value.source.plan.withFilter?.(value.predicate)?.reduce?.('count');
    }
    return undefined;
}

export function windowValue(
    source: RankValue,
    sizeValue: RankValue,
    axes?: readonly number[],
    strideValue?: RankValue,
    paddingValue?: RankValue,
    fillValue?: RankValue,
    wrap = false,
): RankValue {
    fillValue ??= isRankArray(source) && arrayElementTypes(source)?.join() === 'real' ? 0 : 0n;
    if (isRankArray(fillValue) || isRankSequence(fillValue) || isRankQueue(fillValue)) {
        throw new RankError('window padding fill must be a single value');
    }
    if (wrap && !isRankArray(source)) throw new RankError('window wrap expects an array', 'TypeError');
    const widths = windowWidths(sizeValue);
    if (widths.some(width => width <= 0)) {
        throw new RankError('window sizes must be positive integers');
    }
    const strides = windowGeometry(strideValue, widths.length, 'strides', 1);
    if (strides.some(stride => stride <= 0)) {
        throw new RankError('window strides must be positive integers');
    }
    const padding = windowGeometry(paddingValue, widths.length, 'padding', 0);
    if (padding.some(amount => amount < 0)) {
        throw new RankError('window padding must be nonnegative integers');
    }

    if (typeof source === 'string') {
        validateWindowAxes(1, widths, axes);
        rejectWindowPadding(padding, 'text');
        const atoms = [...source];
        const width = widths[0];
        const stride = strides[0];
        const count = windowCount(atoms.length, width, stride, 0);
        return sequence({
            name: `${width} window over text`,
            size: { kind: 'exact', value: BigInt(count) },
            *iterate() {
                for (let start = 0; start + width <= atoms.length; start += stride) {
                    yield atoms.slice(start, start + width).join('');
                }
            },
            at(index) {
                const start = Number(index) * stride;
                if (!Number.isSafeInteger(start) || start < 0 || start + width > atoms.length) {
                    return undefined;
                }
                return atoms.slice(start, start + width).join('');
            },
        });
    }

    if (isRankSequence(source)) {
        validateWindowAxes(1, widths, axes);
        rejectWindowPadding(padding, 'sequence');
        if (source.plan.size.kind !== 'exact' || source.plan.singlePass) {
            return streamingWindows(source, widths[0], strides[0]);
        }
        const length = safeSize(source.plan.size.value, 'sequence size');
        const sourceItem = (index: number) => atSequence(source, BigInt(index));
        const values = source.plan.at ? undefined
            : () => exactWindowCells(source, length, widths[0], strides[0]);
        return arrayWindows(
            [length],
            sourceItem,
            widths,
            [0],
            strides,
            padding,
            fillValue,
            [source],
            false,
            values,
        );
    }

    if (isRankQueue(source)) {
        const items = [...source.items];
        validateWindowAxes(1, widths, axes);
        rejectWindowPadding(padding, 'queue');
        return arrayWindows(
            [items.length],
            index => items[index],
            widths,
            [0],
            strides,
            padding,
            fillValue,
            [ownedArray(items)],
        );
    }

    if (!isRankArray(source)) {
        throw new RankError('window expects text, a sequence or an array');
    }
    const selectedAxes = validateWindowAxes(source.shape.length, widths, axes);
    return arrayWindows(
        source.shape,
        index => source.itemAt?.(index) ?? source.items[index],
        widths,
        selectedAxes,
        strides,
        padding,
        fillValue,
        [source],
        wrap,
    );
}

/** Move items along one axis of an array; vacated positions read the fill value. */
export function shiftValue(
    source: RankValue,
    amountValue: RankValue,
    fillValue: RankValue = 0n,
    axis = 0,
): RankValue {
    if (typeof amountValue !== 'bigint') throw new RankError('shift amount must be an integer');
    if (isRankArray(fillValue) || isRankSequence(fillValue) || isRankQueue(fillValue)) {
        throw new RankError('shift fill must be a single value');
    }
    if (!isRankArray(source)) throw new RankError('shift expects an array');
    axis = resolveAxis(axis, source.shape.length, axis => new RankError(`shift axis out of bounds: ${axis}`));
    const amount = Number(amountValue);
    if (!Number.isSafeInteger(amount)) throw new RankError('shift amount is too large');
    const shape = source.shape;
    const stride = shape.slice(axis + 1).reduce((size, dimension) => size * dimension, 1);
    const result = derivedArray(shape, [source, fillValue], linear => {
        const coordinate = Math.floor(linear / stride) % shape[axis] - amount;
        if (coordinate < 0 || coordinate >= shape[axis]) return fillValue;
        return readArrayItem(source, linear - amount * stride);
    });
    registerPackedBooleanShift(result, source, amount, fillValue, axis);
    registerTensorShift(result, source, amount, fillValue, axis);
    return result;
}

function windowWidths(value: RankValue): number[] {
    const values = typeof value === 'bigint'
        ? [value]
        : isRankArray(value) && value.shape.length === 1
            ? value.items
            : undefined;
    if (!values || !values.every(item => typeof item === 'bigint')) {
        throw new RankError('window size must be an integer or a rank-1 integer array');
    }
    return values.map(item => safeSize(item as bigint, 'window size'));
}

function windowGeometry(
    value: RankValue | undefined,
    count: number,
    name: string,
    fallback: number,
): number[] {
    if (value === undefined) return Array(count).fill(fallback) as number[];
    const values = typeof value === 'bigint'
        ? Array(count).fill(value) as bigint[]
        : isRankArray(value) && value.shape.length === 1
            ? value.items
            : undefined;
    if (!values || !values.every(item => typeof item === 'bigint')) {
        throw new RankError(`window ${name} must be integers`);
    }
    if (values.length !== count) {
        throw new RankError(`window has ${count} size value but ${values.length} ${name}`);
    }
    return values.map(item => safeSize(item as bigint, `window ${name}`));
}

function rejectWindowPadding(padding: readonly number[], source: string): void {
    if (padding.some(amount => amount !== 0)) {
        throw new RankError(`window padding does not support ${source}`);
    }
}

function validateWindowAxes(
    rank: number,
    widths: readonly number[],
    axes: readonly number[] | undefined,
): readonly number[] {
    const selected = axes ? axes.map(axis => resolveAxis(axis, rank, axis => new RankError(`window axis out of bounds: ${axis}`))) : (rank === 1 && widths.length === 1
        ? [0]
        : Array.from({ length: rank }, (_, index) => index));
    if (selected.length !== widths.length) {
        throw new RankError(
            `window has ${widths.length} size value but ${selected.length} selected axes`,
        );
    }
    if (new Set(selected).size !== selected.length) {
        throw new RankError('window axis numbers must be unique');
    }
    return selected;
}

type CellFold = (start: number, operation: (a: RankValue, b: RankValue) => RankValue) => RankValue;
const windowCells = new WeakMap<RankArray, { size: number; fold: CellFold }>();

/** Compose a complete appended window cell with a left fold. No values are
 * cached or forced while selecting this path; readers keep their usual order. */
export function reduceWindowCell(
    value: RankArray, start: number, size: number,
    operation: (a: RankValue, b: RankValue) => RankValue,
): RankValue | undefined {
    const plan = windowCells.get(value);
    if (!plan || size !== plan.size || start % size !== 0) return undefined;
    return plan.fold(start / size, operation);
}

function arrayWindows(
    sourceShape: readonly number[],
    sourceItem: (index: number) => RankValue,
    widths: readonly number[],
    axes: readonly number[],
    strides: readonly number[],
    padding: readonly number[],
    fill: RankValue,
    dependencies: readonly RankValue[],
    wrap = false,
    values?: () => IterableIterator<RankValue>,
): RankArray {
    if (wrap && sourceShape.some(n => n === 0) && padding.some(n => n > 0)) {
        throw new RankError('window wrap cannot pad an empty axis', 'DomainError');
    }
    const readInput = (coordinates: readonly number[]): RankValue => {
        if (wrap) return sourceItem(arrayOffset(sourceShape, coordinates.map((n, axis) =>
            ((n % sourceShape[axis]) + sourceShape[axis]) % sourceShape[axis])));
        return coordinates.some((n, axis) => n < 0 || n >= sourceShape[axis])
            ? fill : sourceItem(arrayOffset(sourceShape, coordinates));
    };
    const positionShape = [...sourceShape];
    const hasPadding = padding.some(amount => amount !== 0);
    axes.forEach((axis, index) => {
        positionShape[axis] = windowCount(
            sourceShape[axis],
            widths[index],
            strides[index],
            padding[index],
        );
    });
    const resultShape = [...positionShape, ...widths];
    const read = (linear: number): RankValue => {
        const output = arrayCoordinates(resultShape, linear);
        const input = output.slice(0, sourceShape.length);
        const offsets = output.slice(sourceShape.length);
        axes.forEach((axis, index) => {
            input[axis] = input[axis] * strides[index]
                - padding[index]
                + offsets[index];
        });
        return hasPadding ? readInput(input) : sourceItem(arrayOffset(sourceShape, input));
    };
    const result = derivedArray(resultShape, hasPadding ? [...dependencies, fill] : dependencies, read,
        dependencies.every(isKnownFileFree) && isKnownFileFree(fill), undefined, values);

    const size = arraySize(widths);
    windowCells.set(result, { size, fold(frameIndex, operation) {
        if (sourceShape.length === 1 && widths.length === 1 && !hasPadding) {
            const start = frameIndex * strides[0];
            let answer = sourceItem(start);
            for (let index = 1; index < size; index++) {
                answer = operation(answer, sourceItem(start + index));
            }
            return answer;
        }
