        const plan = layout;
        if (plan && plan.interruptible === interruptsEnabled() && (implicit || host.builtin(terminal))) {
            const data: ArrayLike<RankValue>[] = [], scalars: RankValue[] = [], offsets = [...plan.offsets];
            const keys: string[] | undefined = hasConcat ? [] : undefined;
